import { mkdirSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'

const root = process.cwd()
const data = [
  {
    id: 'terapeuta-da-fala-na-escola', theme: 'escola', kind: { pt: 'Guia prático', en: 'Practical guide', es: 'Guía práctica' },
    pt: { slug: 'terapeuta-da-fala-na-escola', title: 'O terapeuta da fala na escola: objetivos que chegam à sala de aula', teaser: 'Como ligar comunicação, currículo e participação sem transformar o dia escolar numa sessão.' },
    en: { slug: 'speech-therapist-at-school', title: 'The speech and language therapist at school: goals that reach the classroom', teaser: 'Connecting communication, the curriculum and participation without turning the school day into therapy.' },
    es: { slug: 'logopeda-en-la-escuela', title: 'El logopeda en la escuela: objetivos que llegan al aula', teaser: 'Cómo conectar comunicación, currículo y participación sin convertir el día escolar en una sesión.' },
    content: {
      pt: { lead: 'Uma criança pode saber a resposta e não conseguir dizê-la depressa; pode compreender instruções melhor quando as vê; ou precisar de comunicação aumentativa e alternativa (CAA) para participar. Na escola, a terapia da fala é mais útil quando parte destas barreiras reais e se articula com as atividades da turma.', sections: [
        { h2: 'O que pode trabalhar o terapeuta da fala?', p: ['A intervenção pode abranger compreensão e expressão da linguagem, fala, fluência, voz, comunicação social, literacia emergente e CAA, conforme a avaliação e as competências profissionais. O objetivo não é obter uma criança “mais obediente” ou fazer falar a qualquer custo: é aumentar comunicação funcional, acesso às aprendizagens e participação.', 'Uma dificuldade isolada não determina o plano. A equipa observa o que acontece em diferentes situações — explicar uma ideia, seguir uma instrução, conversar no recreio, pedir ajuda — e identifica pontos fortes, barreiras e prioridades da criança e da família.'] },
        { h2: 'Da sessão à vida da turma', p: ['A terapia pode acontecer individualmente, em pequeno grupo, na sala ou através de consultoria e planeamento com docentes. Não existe um formato único que seja sempre melhor. A decisão depende do objetivo, do contexto e de onde a competência precisa de ser usada; algumas aprendizagens pedem prática focalizada, outras beneficiam de oportunidades naturais ao longo do dia.', 'Uma meta útil descreve uma participação observável: por exemplo, a criança conseguir escolher materiais, responder numa experiência de ciências usando fala, gesto ou CAA, ou pedir esclarecimento. Adultos combinam como modelar, esperar pela resposta e reconhecer diferentes formas de comunicação.'] },
        { h2: 'Como colaborar sem sobrecarregar a criança', p: ['Família, docente e terapeuta podem partilhar exemplos breves e definir um pequeno número de estratégias consistentes. A escola não deve exigir que a criança abandone o seu sistema de comunicação para “provar” que consegue falar. Nem deve presumir que uma estratégia funciona só porque foi treinada numa sala tranquila.', 'Em Portugal, os Centros de Recursos para a Inclusão podem prestar apoio especializado em parceria pedagógica com as escolas, de acordo com a avaliação e as medidas mobilizadas. A disponibilidade concreta e a organização variam; a escola pode explicar quem acompanha a criança, que objetivos foram definidos e como será monitorizado o progresso.'], bullets: ['Descrever a barreira e a situação, não rotular a criança como desinteressada.', 'Manter a CAA acessível nas aulas, recreios, refeições e visitas quando faz parte da comunicação da criança.', 'Rever as metas com a criança e a família, considerando preferências e bem-estar.', 'Observar se a competência aparece em contextos reais, e ajustar o apoio se não generalizar.'] }
      ], summary: ['A terapia da fala na escola deve apoiar comunicação e participação no currículo e na vida escolar.', 'Sessão individual, trabalho em sala e consultoria podem complementar-se; o modelo depende do objetivo e da criança.'], conclusion: 'Uma colaboração eficaz transforma objetivos terapêuticos em oportunidades quotidianas para comunicar e aprender. A fala é uma forma de comunicação, não a única medida de participação.' },
      en: { lead: 'A child may know an answer but be unable to say it quickly, understand instructions better when they are shown, or need augmentative and alternative communication (AAC) to take part. At school, speech and language therapy is most useful when it addresses these real barriers and connects with classroom activities.', sections: [
        { h2: 'What can a speech and language therapist work on?', p: ['Depending on assessment and professional scope, support may address language comprehension and expression, speech, fluency, voice, social communication, early literacy and AAC. The aim is not to make a child “more compliant” or force speech; it is to improve functional communication, access to learning and participation.', 'A single difficulty does not determine a plan. The team looks at different situations — explaining an idea, following instructions, chatting at break, asking for help — and identifies strengths, barriers and priorities with the child and family.'] },
        { h2: 'From a session to classroom life', p: ['Support may be individual, in a small group, in class, or through consultation and planning with teachers. No one format is always best. The choice depends on the goal, context and where the skill needs to be used; some learning calls for focused practice, while other goals benefit from natural opportunities throughout the day.', 'A useful goal describes observable participation: for example, choosing materials, responding in a science activity with speech, gesture or AAC, or asking for clarification. Adults agree how to model, allow response time and acknowledge different ways of communicating.'] },
        { h2: 'Collaborating without overloading the child', p: ['Family, teacher and therapist can share brief examples and agree on a small set of consistent strategies. A child should not have to give up their communication system to “prove” they can speak. Nor should adults assume that a strategy works just because it was practised in a quiet room.', 'In Portugal, Resource Centres for Inclusion may provide specialist support in pedagogical partnership with schools, according to assessment and the measures put in place. Availability and organisation vary. The school can explain who supports the child, which goals were agreed and how progress will be reviewed.'], bullets: ['Describe the barrier and situation instead of labelling a child uninterested.', 'Keep AAC available during lessons, breaks, meals and trips when it is part of the child’s communication.', 'Review goals with the child and family, taking preferences and wellbeing into account.', 'Check whether a skill appears in real settings and adjust support if it does not generalise.'] }
      ], summary: ['School speech and language therapy should support communication, curriculum access and participation in school life.', 'Individual sessions, classroom work and consultation can complement each other; the model depends on the child and the goal.'], conclusion: 'Effective collaboration turns therapy goals into everyday opportunities to communicate and learn. Speech is one way to communicate, not the only measure of participation.' },
      es: { lead: 'Una niña o un niño puede saber la respuesta y no conseguir decirla deprisa; comprender mejor las instrucciones cuando las ve; o necesitar comunicación aumentativa y alternativa (CAA) para participar. En la escuela, la logopedia es más útil cuando parte de esas barreras reales y se conecta con las actividades del aula.', sections: [
        { h2: '¿Qué puede trabajar el logopeda?', p: ['Según la evaluación y sus competencias profesionales, la intervención puede abordar la comprensión y expresión del lenguaje, el habla, la fluidez, la voz, la comunicación social, la alfabetización inicial y la CAA. El objetivo no es conseguir que el niño sea “más obediente” ni forzar el habla: es mejorar la comunicación funcional, el acceso al aprendizaje y la participación.', 'Una dificultad aislada no determina el plan. El equipo observa distintas situaciones —explicar una idea, seguir una instrucción, conversar en el recreo, pedir ayuda— e identifica fortalezas, barreras y prioridades junto con el niño y su familia.'] },
        { h2: 'De la sesión a la vida del aula', p: ['El apoyo puede ser individual, en pequeño grupo, en el aula o mediante consulta y planificación con el profesorado. No existe un formato que sea siempre mejor. La decisión depende del objetivo, del contexto y de dónde se necesita usar la habilidad: algunos aprendizajes requieren práctica específica y otros se benefician de oportunidades naturales durante el día.', 'Una meta útil describe una participación observable: por ejemplo, elegir materiales, responder en una actividad de ciencias mediante habla, gesto o CAA, o pedir una aclaración. Los adultos acuerdan cómo modelar, dar tiempo para responder y reconocer distintas formas de comunicación.'] },
        { h2: 'Colaborar sin sobrecargar al niño', p: ['La familia, el docente y el logopeda pueden compartir ejemplos breves y acordar unas pocas estrategias coherentes. No se debe exigir que el niño deje su sistema de comunicación para “demostrar” que puede hablar. Tampoco conviene asumir que una estrategia funciona solo porque se practicó en una sala tranquila.', 'En Portugal, los Centros de Recursos para la Inclusión pueden prestar apoyo especializado en colaboración pedagógica con las escuelas, según la evaluación y las medidas acordadas. La disponibilidad y organización varían. La escuela puede explicar quién acompaña al niño, qué objetivos se han definido y cómo se revisará el progreso.'], bullets: ['Describir la barrera y la situación, sin etiquetar al niño como desinteresado.', 'Mantener la CAA disponible en clase, recreos, comidas y salidas cuando forma parte de su comunicación.', 'Revisar los objetivos con el niño y la familia, teniendo en cuenta preferencias y bienestar.', 'Observar si la habilidad aparece en situaciones reales y ajustar el apoyo si no se generaliza.'] }
      ], summary: ['La logopedia escolar debe apoyar la comunicación, el acceso al currículo y la participación en la vida escolar.', 'Las sesiones individuales, el trabajo en el aula y la consulta pueden complementarse; el modelo depende del niño y del objetivo.'], conclusion: 'Una colaboración eficaz convierte los objetivos terapéuticos en oportunidades cotidianas para comunicarse y aprender. El habla es una forma de comunicación, no la única medida de participación.' }
    }, sources: ['DGE: <a href="https://www.dge.mec.pt/publicacoes-da-dseeas" target="_blank" rel="noopener">publicações e orientações para terapeutas em contexto escolar</a>.', 'DGE: <a href="https://dge.mec.pt/sites/default/files/EEspecial/necessidades_especiais_de_educacao_parceria_entre_a_escola_e_o_cri_uma_estrategia_para_a_inclusao.pdf" target="_blank" rel="noopener">Parceria entre a Escola e o CRI</a>.', 'ASHA: <a href="https://www.asha.org/SLP/schools/School-Based-Service-Delivery-in-Speech-Language-Pathology/" target="_blank" rel="noopener">School-based service delivery</a>.'], related: ['inclusao-escolar-comunicacao', 'comunicacao-aumentativa-e-alternativa']
  },
  {
    id: 'terapia-ocupacional-na-escola', theme: 'escola', kind: { pt: 'Guia prático', en: 'Practical guide', es: 'Guía práctica' },
    pt: { slug: 'terapia-ocupacional-na-escola', title: 'Terapia ocupacional na escola: participar, escrever, brincar e cuidar de si', teaser: 'O foco não é apenas a letra: é reduzir barreiras nas tarefas e rotinas que fazem parte da escola.' },
    en: { slug: 'occupational-therapy-at-school', title: 'Occupational therapy at school: participating, writing, playing and self-care', teaser: 'The focus is not just handwriting: it is reducing barriers in school tasks and routines.' },
    es: { slug: 'terapia-ocupacional-en-la-escuela', title: 'Terapia ocupacional en la escuela: participar, escribir, jugar y cuidarse', teaser: 'El objetivo no es solo la letra: es reducir barreras en tareas y rutinas escolares.' },
    content: {
      pt: { lead: 'Copiar do quadro, usar tesoura, organizar o material, almoçar no refeitório ou participar no recreio são ocupações escolares. Se uma destas tarefas exige um esforço desproporcionado, a terapia ocupacional pode ajudar a perceber a interação entre a criança, a atividade e o ambiente — e a encontrar adaptações funcionais.', sections: [
        { h2: 'A terapia ocupacional é só para a escrita?', p: ['Não. A escrita manual pode ser uma meta, mas a terapia ocupacional em contexto escolar olha para participação em atividades académicas, não académicas, sociais e de autocuidado. Pode apoiar acesso a materiais, vestir o casaco para a educação física, gerir talheres, deslocar-se pela escola ou integrar uma atividade de grupo.', 'A pergunta orientadora é “o que está a impedir a participação nesta rotina?”. A dificuldade pode estar na tarefa, no espaço, no tempo, nos materiais, nas exigências sensoriais ou na forma como a ajuda é dada. Uma avaliação observa o desempenho em contexto e escuta a criança, a família e os docentes.'] },
        { h2: 'Adaptar a atividade e o ambiente', p: ['Uma solução não precisa de começar por treinar a criança fora da sala. Pode envolver uma pega diferente, uma folha com melhor contraste, instruções por etapas, mais tempo, mudança de lugar, reduzir estímulos que distraem ou reorganizar a sequência de uma tarefa. A adaptação deve ser testada na atividade real e revista com base no que melhora o acesso e a autonomia.', 'A integração sensorial é uma área da terapia ocupacional, mas não explica todas as dificuldades nem justifica automaticamente dietas sensoriais ou equipamentos. As estratégias devem ter objetivo claro, avaliação individual e monitorização. Uma almofada, um objeto de manipulação ou uma pausa só são úteis se ajudarem a criança a participar com segurança e sem a excluir.'] },
        { h2: 'Metas partilhadas com a escola', p: ['O terapeuta pode trabalhar diretamente com a criança, colaborar com o docente ou propor alterações de ambiente; estes formatos podem combinar-se. No enquadramento português, o apoio dos CRI é uma parceria com a escola e procura habilitar também os contextos. A terapia não substitui o ensino nem transfere para o técnico toda a responsabilidade pela acessibilidade.', 'Para acompanhar resultados, registe uma tarefa concreta, o nível de ajuda necessário e o que mudou após a adaptação. A criança deve poder dizer o que lhe facilita ou dificulta a rotina, usando a sua forma de comunicação.'], bullets: ['Escolher metas relacionadas com atividades que a criança valoriza e precisa de fazer.', 'Observar a tarefa na sala, no recreio, nas refeições ou nas transições, conforme a dificuldade.', 'Combinar a mesma adaptação com os adultos que acompanham a rotina.', 'Evitar atribuir toda a dificuldade a falta de esforço, motivação ou “má postura”.'] }
      ], summary: ['A terapia ocupacional escolar procura aumentar o acesso e a participação em tarefas importantes do dia escolar.', 'A intervenção pode ajustar competências, materiais, atividade ou ambiente e deve ser avaliada no contexto real.'], conclusion: 'Uma adaptação bem escolhida torna possível fazer mais, com segurança e autonomia. O sucesso mede-se pela participação significativa, não pela normalização de cada movimento.' },
      en: { lead: 'Copying from the board, using scissors, organising materials, eating in the canteen and joining playground activities are all part of school life. When a task takes disproportionate effort, occupational therapy can examine how the child, activity and environment interact — and identify functional adjustments.', sections: [
        { h2: 'Is school occupational therapy only about handwriting?', p: ['No. Handwriting can be a goal, but school-based occupational therapy considers participation in academic, non-academic, social and self-care activities. It may support access to materials, putting on a coat for PE, using cutlery, moving around school or joining a group activity.', 'The guiding question is “what is getting in the way of participation in this routine?” The barrier may relate to the task, space, time, materials, sensory demands or the way help is offered. Assessment considers performance in context and listens to the child, family and teachers.'] },
        { h2: 'Adjusting the task and environment', p: ['A solution need not start by practising outside the classroom. It may involve a different pencil grip, higher-contrast paper, step-by-step instructions, extra time, a change of seat, fewer distracting stimuli or a different task sequence. The adjustment should be tried during the real activity and reviewed according to whether it improves access and independence.', 'Sensory integration is one area of occupational therapy, but it does not explain every difficulty or automatically justify sensory diets or equipment. Strategies need a clear purpose, individual assessment and monitoring. A cushion, fidget or break is useful only if it helps the child participate safely without exclusion.'] },
        { h2: 'Goals shared with the school', p: ['A therapist may work directly with the child, collaborate with a teacher or recommend environmental changes; these approaches can be combined. In Portugal, support from CRI is a partnership with the school that also aims to build the capacity of the environment. Therapy does not replace teaching or make the therapist solely responsible for accessibility.', 'To review outcomes, record a specific task, the amount of help needed and what changed after an adjustment. The child should be able to share what helps or hinders the routine, using their preferred communication.'], bullets: ['Choose goals linked to activities the child values and needs to do.', 'Observe the task in class, at break, at meals or during transitions, as relevant.', 'Agree on the same adjustment with the adults supporting the routine.', 'Avoid explaining every difficulty as lack of effort, motivation or “bad posture”.'] }
      ], summary: ['School occupational therapy aims to improve access and participation in meaningful school activities.', 'Support may adapt skills, materials, tasks or environments and should be reviewed in the real context.'], conclusion: 'A well-chosen adjustment makes it possible to do more, safely and independently. Success means meaningful participation, not normalising every movement.' },
      es: { lead: 'Copiar de la pizarra, usar tijeras, organizar el material, comer en el comedor o participar en el recreo son actividades escolares. Si una tarea exige un esfuerzo desproporcionado, la terapia ocupacional puede analizar cómo interactúan el niño, la actividad y el entorno, y buscar ajustes funcionales.', sections: [
        { h2: '¿La terapia ocupacional escolar trata solo la escritura?', p: ['No. La escritura puede ser un objetivo, pero la terapia ocupacional en la escuela considera la participación en actividades académicas, no académicas, sociales y de autocuidado. Puede apoyar el acceso a materiales, ponerse el abrigo para educación física, usar cubiertos, desplazarse por la escuela o integrarse en una actividad grupal.', 'La pregunta orientadora es “¿qué impide participar en esta rutina?”. La barrera puede estar en la tarea, el espacio, el tiempo, los materiales, las exigencias sensoriales o la forma de ofrecer ayuda. La evaluación observa el desempeño en contexto y escucha al niño, a la familia y al profesorado.'] },
        { h2: 'Adaptar la actividad y el entorno', p: ['Una solución no tiene que empezar por entrenar al niño fuera del aula. Puede consistir en un lápiz distinto, una hoja con más contraste, instrucciones por pasos, más tiempo, cambiar de sitio, reducir estímulos distractores o reorganizar una tarea. El ajuste debe probarse en la actividad real y revisarse según mejore el acceso y la autonomía.', 'La integración sensorial es un ámbito de la terapia ocupacional, pero no explica todas las dificultades ni justifica automáticamente dietas sensoriales o equipamiento. Las estrategias necesitan un objetivo claro, evaluación individual y seguimiento. Un cojín, un objeto manipulable o una pausa solo son útiles si facilitan la participación segura sin excluir al niño.'] },
        { h2: 'Objetivos compartidos con la escuela', p: ['El terapeuta puede trabajar directamente con el niño, colaborar con el docente o proponer cambios en el entorno; estos formatos pueden combinarse. En Portugal, el apoyo de los CRI es una colaboración con la escuela que también busca capacitar los contextos. La terapia no sustituye la enseñanza ni hace responsable al técnico de toda la accesibilidad.', 'Para revisar resultados, anota una tarea concreta, el nivel de ayuda necesario y qué cambió tras el ajuste. El niño debe poder explicar qué facilita o dificulta la rutina, mediante su forma de comunicación.'], bullets: ['Elegir objetivos vinculados a actividades que el niño valora y necesita hacer.', 'Observar la tarea en clase, recreo, comedor o transiciones, según corresponda.', 'Acordar el mismo ajuste con los adultos que acompañan la rutina.', 'Evitar atribuir toda dificultad a falta de esfuerzo, motivación o “mala postura”.'] }
      ], summary: ['La terapia ocupacional escolar busca mejorar el acceso y la participación en actividades escolares importantes.', 'El apoyo puede adaptar habilidades, materiales, tareas o entornos y debe revisarse en el contexto real.'], conclusion: 'Un ajuste bien elegido permite hacer más, con seguridad y autonomía. El éxito se mide por la participación significativa, no por normalizar cada movimiento.' }
    }, sources: ['DGE: <a href="https://www.dge.mec.pt/publicacoes-da-dseeas" target="_blank" rel="noopener">O Terapeuta Ocupacional em Contexto Escolar</a>.', 'AOTA: <a href="https://www.aota.org/practice/practice-settings/schools-early-intervention-community-education/schools" target="_blank" rel="noopener">School-based occupational therapy</a>.', 'Systematic review: <a href="https://pubmed.ncbi.nlm.nih.gov/36170879/" target="_blank" rel="noopener">Targeting the school environment to enable participation</a>.'], related: ['inclusao-escolar-comunicacao', 'personalizacao-da-aprendizagem-infantil']
  },
  {
    id: 'psicologia-escolar-neurodivergencia', theme: 'escola', kind: { pt: 'Guia prático', en: 'Practical guide', es: 'Guía práctica' },
    pt: { slug: 'psicologia-escolar-neurodivergencia', title: 'Psicologia escolar e neurodivergência: apoiar sem reduzir a criança ao diagnóstico', teaser: 'O que pode fazer o psicólogo escolar e como ligar bem-estar, aprendizagem e participação.' },
    en: { slug: 'school-psychology-neurodiversity', title: 'School psychology and neurodiversity: support without reducing a child to a diagnosis', teaser: 'What a school psychologist can do and how to connect wellbeing, learning and participation.' },
    es: { slug: 'psicologia-escolar-neurodivergencia', title: 'Psicología escolar y neurodivergencia: apoyar sin reducir al niño al diagnóstico', teaser: 'Qué puede hacer el psicólogo escolar y cómo conectar bienestar, aprendizaje y participación.' },
    content: {
      pt: { lead: 'Ansiedade, sobrecarga, dificuldades de atenção ou conflito com colegas podem afetar a aprendizagem. O psicólogo escolar pode ajudar a compreender o que está a acontecer e a coordenar respostas com a criança, a família e a equipa educativa — sem tratar uma diferença neurológica como falha de caráter.', sections: [
        { h2: 'O papel do psicólogo na escola', p: ['O trabalho pode incluir observação, consulta a docentes e família, avaliação psicológica dentro das competências profissionais, aconselhamento, promoção de saúde mental e apoio à equipa na escolha de estratégias. No quadro português, o psicólogo integra os elementos permanentes da EMAEI; a participação de outros técnicos depende das necessidades e organização da escola.', 'Um comportamento é informação sobre uma interação, não um diagnóstico por si só. Antes de concluir que a criança “não quer”, a equipa pode explorar se a instrução foi compreendida, se a tarefa está acessível, se há ruído, dor, medo, cansaço ou uma experiência de exclusão.'] },
        { h2: 'Bem-estar e aprendizagem caminham juntos', p: ['Apoios eficazes definem objetivos observáveis: sentir-se seguro para pedir uma pausa, voltar gradualmente a uma atividade, compreender as regras de um trabalho de grupo ou reduzir uma barreira que desencadeia ansiedade. A criança deve participar no plano de acordo com a idade e comunicação; as estratégias não devem exigir mascarar traços autistas ou suportar sofrimento para parecer “bem adaptada”.', 'Se os sinais forem persistentes ou intensos, a escola e a família podem articular com profissionais de saúde. A intervenção escolar não substitui cuidados clínicos, e um diagnóstico clínico não determina automaticamente uma medida escolar: a resposta educativa deve considerar a participação e as barreiras no contexto.'] },
        { h2: 'Privacidade, consentimento e acompanhamento', p: ['Partilhe apenas a informação necessária para apoiar a criança e use canais seguros. O processo individual está sujeito a regras de confidencialidade e proteção de dados. A equipa deve explicar quem acede aos registos, como os dados orientam as medidas e quando o plano será revisto.', 'As famílias podem levar exemplos concretos e perguntar que mudanças serão testadas, quem as acompanha e como será verificado o efeito. Se a criança comunica que uma estratégia a deixa desconfortável, esse sinal merece ser escutado e discutido.'], bullets: ['Descrever acontecimentos e contextos em vez de interpretar intenções.', 'Combinar um objetivo de bem-estar e outro de participação escolar.', 'Evitar prometer que uma técnica resolve todas as dificuldades.', 'Rever a resposta com a criança, a família e os docentes.'] }
      ], summary: ['O psicólogo escolar ajuda a compreender necessidades e a coordenar respostas educativas e de bem-estar.', 'Diagnóstico e comportamento não substituem a observação das barreiras concretas nem a voz da criança.'], conclusion: 'O apoio psicológico escolar é mais útil quando melhora segurança, participação e aprendizagem, respeitando identidade, privacidade e preferências.' },
      en: { lead: 'Anxiety, overload, attention difficulties or peer conflict can affect learning. A school psychologist can help make sense of what is happening and coordinate responses with the child, family and education team — without treating neurological difference as a character flaw.', sections: [
        { h2: 'The school psychologist’s role', p: ['Work may include observation, consultation with teachers and family, assessment within professional scope, counselling, mental health promotion and helping the team choose strategies. In Portugal, a psychologist is a permanent member of the EMAEI; involvement of other professionals depends on the child’s needs and the school’s organisation.', 'Behaviour is information about an interaction, not a diagnosis by itself. Before concluding that a child “doesn’t want to”, the team can explore whether instructions were understood, the task is accessible, or noise, pain, fear, fatigue or exclusion is involved.'] },
        { h2: 'Wellbeing and learning belong together', p: ['Helpful support sets observable goals: feeling safe enough to ask for a break, gradually returning to an activity, understanding group-work expectations or reducing a barrier that triggers anxiety. The child should participate in planning in a way suited to their age and communication. Strategies should not require masking autistic traits or enduring distress to appear “well adjusted”.', 'When signs are persistent or intense, school and family can coordinate with health professionals. School support does not replace clinical care, and a clinical diagnosis does not automatically determine a school measure: the educational response considers participation and barriers in context.'] },
        { h2: 'Privacy, consent and review', p: ['Share only information needed to support the child and use secure channels. The student record is subject to confidentiality and data-protection rules. The team should explain who can access records, how information guides support and when the plan will be reviewed.', 'Families can bring specific examples and ask what changes will be tried, who will coordinate them and how their effect will be checked. If a child says a strategy feels uncomfortable, that signal deserves to be heard and discussed.'], bullets: ['Describe events and contexts instead of assuming intentions.', 'Agree on one wellbeing goal and one school-participation goal.', 'Avoid promising that one technique will solve every difficulty.', 'Review support with the child, family and teachers.'] }
      ], summary: ['A school psychologist can help understand needs and coordinate educational and wellbeing support.', 'A diagnosis or behaviour does not replace looking at concrete barriers or listening to the child.'], conclusion: 'School psychological support is most useful when it improves safety, participation and learning while respecting identity, privacy and preferences.' },
      es: { lead: 'La ansiedad, la sobrecarga, las dificultades de atención o los conflictos con compañeros pueden afectar al aprendizaje. El psicólogo escolar puede ayudar a comprender qué ocurre y coordinar respuestas con el niño, la familia y el equipo educativo, sin tratar la diferencia neurológica como un defecto de carácter.', sections: [
        { h2: 'El papel del psicólogo en la escuela', p: ['El trabajo puede incluir observación, consulta al profesorado y a la familia, evaluación dentro de sus competencias, asesoramiento, promoción de la salud mental y apoyo al equipo para elegir estrategias. En Portugal, el psicólogo forma parte de los miembros permanentes de la EMAEI; la participación de otros profesionales depende de las necesidades y de la organización escolar.', 'La conducta informa de una interacción; no es un diagnóstico por sí sola. Antes de concluir que el niño “no quiere”, el equipo puede explorar si entendió la instrucción, si la tarea es accesible y si influyen el ruido, el dolor, el miedo, el cansancio o la exclusión.'] },
        { h2: 'Bienestar y aprendizaje van juntos', p: ['El apoyo útil define objetivos observables: sentirse seguro para pedir una pausa, volver poco a poco a una actividad, comprender las reglas de un trabajo en grupo o reducir una barrera que provoca ansiedad. El niño debe participar en el plan según su edad y comunicación. Las estrategias no deben exigir que oculte rasgos autistas o soporte malestar para parecer “bien adaptado”.', 'Si las señales son persistentes o intensas, la escuela y la familia pueden coordinarse con profesionales de salud. La intervención escolar no sustituye la atención clínica, y un diagnóstico no determina automáticamente una medida educativa: la respuesta debe considerar la participación y las barreras del contexto.'] },
        { h2: 'Privacidad, consentimiento y seguimiento', p: ['Comparte solo la información necesaria para apoyar al niño y utiliza canales seguros. El expediente del alumno está sujeto a normas de confidencialidad y protección de datos. El equipo debe explicar quién accede a los registros, cómo orientan las medidas y cuándo se revisará el plan.', 'La familia puede aportar ejemplos concretos y preguntar qué cambios se probarán, quién los coordinará y cómo se evaluará el efecto. Si el niño comunica que una estrategia le incomoda, esa señal merece ser escuchada y debatida.'], bullets: ['Describir hechos y contextos en vez de atribuir intenciones.', 'Acordar un objetivo de bienestar y otro de participación escolar.', 'No prometer que una técnica resolverá todas las dificultades.', 'Revisar el apoyo con el niño, la familia y el profesorado.'] }
      ], summary: ['El psicólogo escolar ayuda a comprender necesidades y coordinar respuestas educativas y de bienestar.', 'El diagnóstico y la conducta no sustituyen la observación de barreras concretas ni la voz del niño.'], conclusion: 'El apoyo psicológico escolar es más útil cuando mejora la seguridad, la participación y el aprendizaje, respetando identidad, privacidad y preferencias.' }
    }, sources: ['Diário da República: <a href="https://diariodarepublica.pt/dr/legislacao-consolidada/decreto-lei/2018-115654476" target="_blank" rel="noopener">Decreto-Lei n.º 54/2018, redação consolidada (EMAEI e princípios)</a>.', 'NICE: <a href="https://www.nice.org.uk/guidance/cg170" target="_blank" rel="noopener">Autism spectrum disorder in under 19s: support and management</a>.', 'DGE: <a href="https://webinars.dge.mec.pt/webinar/nee-o-psicologo-do-cri-em-contexto-escolar" target="_blank" rel="noopener">O Psicólogo do CRI em contexto escolar</a>.'], related: ['mutismo-seletivo', 'autismo-e-comunicacao']
  },
  {
    id: 'fisioterapia-na-escola', theme: 'escola', kind: { pt: 'Guia prático', en: 'Practical guide', es: 'Guía práctica' },
    pt: { slug: 'fisioterapia-na-escola', title: 'Fisioterapia na escola: mobilidade, conforto e participação', teaser: 'Como pensar o acesso ao recreio, às aulas e às atividades sem reduzir o aluno à sua mobilidade.' },
    en: { slug: 'physiotherapy-at-school', title: 'Physiotherapy at school: mobility, comfort and participation', teaser: 'Making lessons, playgrounds and activities accessible without defining a pupil by mobility.' },
    es: { slug: 'fisioterapia-en-la-escuela', title: 'Fisioterapia en la escuela: movilidad, comodidad y participación', teaser: 'Cómo facilitar clases, recreo y actividades sin reducir al alumno a su movilidad.' },
    content: {
      pt: { lead: 'Para participar numa visita de estudo, numa aula de educação física ou simplesmente deslocar-se entre salas, a criança pode precisar de acessibilidade física, equipamento, tempo e apoio combinado. A fisioterapia em contexto escolar deve ligar competências motoras às rotinas e escolhas que importam para o aluno.', sections: [
        { h2: 'O foco é a função no contexto escolar', p: ['A fisioterapia pode apoiar mobilidade, postura, transferências, acesso a espaços e participação segura em atividades. O plano parte de objetivos funcionais definidos com a criança, a família e a escola. Melhorar um movimento fora do seu contexto pode não resolver a barreira se o corredor continuar inacessível ou se a atividade não admitir formas diferentes de participação.', 'O fisioterapeuta pode observar a rotina, aconselhar a equipa, testar produtos de apoio e colaborar com outros profissionais. A intervenção não deve presumir que todas as crianças com o mesmo diagnóstico precisam do mesmo apoio, nem que a participação depende de caminhar sem ajuda.'] },
        { h2: 'Educação física, recreio e visitas', p: ['Atividades físicas podem ser adaptadas para manter o objetivo pedagógico e oferecer participação significativa: ajustar regras, equipamento, distância, papel no grupo ou pausas. A escola pode verificar percursos, casas de banho, rampas, transporte e acesso aos espaços comuns antes de uma saída.', 'Segurança não significa retirar automaticamente a criança. Avaliam-se riscos concretos e formas razoáveis de os reduzir, envolvendo o aluno e a família. O apoio necessário pode mudar com a fadiga, o terreno, a saúde e a atividade.'] },
        { h2: 'Planear e acompanhar', p: ['O Decreto-Lei n.º 54/2018 organiza recursos e medidas em torno da participação e da aprendizagem, e prevê articulação com recursos especializados da comunidade quando necessária. O modo de disponibilização da fisioterapia escolar varia entre escolas e territórios; é útil perguntar qual é o circuito local e como se articula com a equipa de saúde.', 'Combine uma meta observável — por exemplo, chegar à biblioteca, participar numa atividade adaptada ou realizar uma transferência com a ajuda acordada — e reveja se o espaço e os apoios permitem que aconteça com dignidade e segurança.'], bullets: ['Perguntar ao aluno que atividades quer conseguir fazer.', 'Mapear barreiras físicas e organizacionais antes de decidir a solução.', 'Planear pausas e níveis de apoio sem retirar oportunidades de aprendizagem.', 'Rever o plano quando mudam as rotinas, o equipamento ou a condição de saúde.'] }
      ], summary: ['A fisioterapia escolar liga movimento e acesso às atividades reais da escola.', 'A participação pode exigir adaptações do espaço, da atividade e dos apoios, não apenas treino individual.'], conclusion: 'Uma escola acessível planeia as atividades para que mobilidade, segurança e pertença possam coexistir.' },
      en: { lead: 'To join a field trip, take part in PE or simply move between classrooms, a child may need physical access, equipment, time and coordinated support. School physiotherapy should connect motor skills with routines and choices that matter to the pupil.', sections: [
        { h2: 'The focus is function in the school context', p: ['Physiotherapy may support mobility, positioning, transfers, access to spaces and safe participation. Planning starts with functional goals agreed with the child, family and school. Improving a movement outside its context may not remove the barrier if a corridor remains inaccessible or an activity allows only one way to take part.', 'A physiotherapist may observe routines, advise the team, trial assistive products and collaborate with other professionals. Support should not assume that pupils with the same diagnosis need the same help, or that participation depends on walking unaided.'] },
        { h2: 'PE, break time and trips', p: ['Physical activities can be adapted while keeping the learning objective and offering meaningful participation: change rules, equipment, distance, group role or breaks. Before a trip, the school can check routes, toilets, ramps, transport and access to shared spaces.', 'Safety does not mean automatically excluding the pupil. Assess specific risks and reasonable ways to reduce them, involving the student and family. Support needs may change with fatigue, terrain, health and activity.'] },
        { h2: 'Planning and review', p: ['Portugal’s Decree-Law 54/2018 organises measures around participation and learning and provides for collaboration with specialist community resources when needed. How school physiotherapy is delivered varies between schools and regions; families can ask about local arrangements and links with the health team.', 'Agree on an observable goal — reaching the library, joining an adapted activity or completing an agreed transfer — then review whether the space and support make it possible with dignity and safety.'], bullets: ['Ask the pupil which activities they want to do.', 'Map physical and organisational barriers before choosing a solution.', 'Plan breaks and support levels without removing learning opportunities.', 'Review the plan when routines, equipment or health needs change.'] }
      ], summary: ['School physiotherapy connects movement with real school activities.', 'Participation may require changes to spaces, tasks and support, not only individual practice.'], conclusion: 'An accessible school plans activities so mobility, safety and belonging can coexist.' },
      es: { lead: 'Para participar en una excursión, en educación física o simplemente desplazarse entre aulas, el niño puede necesitar accesibilidad física, equipo, tiempo y apoyos coordinados. La fisioterapia escolar debe relacionar las habilidades motoras con rutinas y elecciones importantes para el alumno.', sections: [
        { h2: 'El objetivo es la función en el contexto escolar', p: ['La fisioterapia puede apoyar la movilidad, la postura, las transferencias, el acceso a espacios y la participación segura. El plan parte de objetivos funcionales acordados con el niño, la familia y la escuela. Mejorar un movimiento fuera de contexto no elimina la barrera si un pasillo sigue siendo inaccesible o la actividad solo permite una forma de participar.', 'El fisioterapeuta puede observar rutinas, asesorar al equipo, probar productos de apoyo y colaborar con otros profesionales. No debe suponerse que todos los niños con el mismo diagnóstico necesitan el mismo apoyo ni que participar exige caminar sin ayuda.'] },
        { h2: 'Educación física, recreo y excursiones', p: ['Las actividades físicas pueden adaptarse conservando el objetivo pedagógico y ofreciendo una participación significativa: cambiar reglas, material, distancia, papel en el grupo o pausas. Antes de una salida, la escuela puede revisar recorridos, aseos, rampas, transporte y acceso a los espacios comunes.', 'La seguridad no significa excluir automáticamente al alumno. Se valoran riesgos concretos y formas razonables de reducirlos, contando con el niño y la familia. El apoyo necesario puede cambiar con el cansancio, el terreno, la salud y la actividad.'] },
        { h2: 'Planificar y revisar', p: ['El Decreto-ley portugués 54/2018 organiza medidas en torno a la participación y el aprendizaje, y prevé colaboración con recursos especializados de la comunidad cuando haga falta. La forma de ofrecer fisioterapia escolar varía entre centros y territorios; conviene preguntar por el circuito local y la coordinación con salud.', 'Acuerda una meta observable —llegar a la biblioteca, participar en una actividad adaptada o realizar una transferencia planificada— y revisa si el espacio y los apoyos lo permiten con dignidad y seguridad.'], bullets: ['Preguntar al alumno qué actividades desea realizar.', 'Identificar barreras físicas y organizativas antes de elegir una solución.', 'Planificar pausas y apoyos sin eliminar oportunidades de aprendizaje.', 'Revisar el plan cuando cambien las rutinas, el equipo o la salud.'] }
      ], summary: ['La fisioterapia escolar conecta el movimiento con actividades reales de la escuela.', 'Participar puede requerir adaptar espacios, tareas y apoyos, además del trabajo individual.'], conclusion: 'Una escuela accesible planifica las actividades para que movilidad, seguridad y pertenencia puedan coexistir.' }
    }, sources: ['DGE: <a href="https://www.dge.mec.pt/publicacoes-da-dseeas" target="_blank" rel="noopener">O Fisioterapeuta em Contexto Escolar</a>.', 'Diário da República: <a href="https://diariodarepublica.pt/dr/legislacao-consolidada/decreto-lei/2018-115654476" target="_blank" rel="noopener">Decreto-Lei n.º 54/2018, redação consolidada</a>.', 'UNESCO: <a href="https://www.unesco.org/en/inclusion-education" target="_blank" rel="noopener">Inclusion in education</a>.'], related: ['inclusao-escolar-comunicacao', 'personalizacao-da-aprendizagem-infantil']
  },
  {
    id: 'centros-recursos-inclusao-escola', theme: 'escola', kind: { pt: 'Guia de apoios', en: 'Support guide', es: 'Guía de apoyos' },
    pt: { slug: 'centros-recursos-inclusao-escola', title: 'CRI: como pode funcionar a parceria entre a escola e os terapeutas', teaser: 'O que são os Centros de Recursos para a Inclusão, que profissionais podem envolver e como articular objetivos.' },
    en: { slug: 'inclusion-resource-centres-schools', title: 'CRI: how school and therapy partnerships can work', teaser: 'What Portugal’s Resource Centres for Inclusion do and how to coordinate shared goals.' },
    es: { slug: 'centros-recursos-inclusion-escuela', title: 'CRI: cómo puede funcionar la colaboración entre escuela y terapeutas', teaser: 'Qué son los Centros de Recursos para la Inclusión y cómo coordinar objetivos compartidos.' },
    content: {
      pt: { lead: 'Um Centro de Recursos para a Inclusão (CRI) é um serviço especializado da comunidade que pode apoiar a escola na resposta a necessidades de aprendizagem e participação. Não é uma escola alternativa nem um pacote igual para todas as crianças: é uma parceria cuja organização depende da avaliação, dos objetivos e dos recursos mobilizados.', sections: [
        { h2: 'O que é e o que pode disponibilizar?', p: ['O Decreto-Lei n.º 54/2018 descreve os CRI como serviços especializados acreditados que apoiam a capacidade da escola para promover o sucesso educativo e a inclusão. As equipas podem incluir terapeutas da fala, terapeutas ocupacionais, fisioterapeutas, psicólogos ou outros profissionais, conforme a entidade e o acordo em vigor.', 'O apoio pode incluir intervenção direta, observação de atividades, aconselhamento, formação e planeamento conjunto. A intenção é aproximar competências especializadas dos contextos onde a criança aprende e participa, em vez de trabalhar apenas objetivos descontextualizados. Os formatos e a disponibilidade não são idênticos em todas as regiões.'] },
        { h2: 'A escola continua a ser responsável pela resposta educativa', p: ['O CRI complementa a escola; não substitui o professor, a equipa multidisciplinar nem as medidas de suporte definidas pela escola. O artigo 18.º prevê uma parceria pedagógica e de desenvolvimento. Na prática, os objetivos especializados devem ligar-se às atividades e à participação do aluno, e a equipa deve combinar quem faz o quê e como partilha informação.', 'A família pode perguntar que objetivos estão no plano, quando e em que contexto acontece o apoio, como os profissionais articulam e o que será revisto. Se um apoio acontece fora da sala, vale a pena conversar sobre a razão, a duração e a forma de transferir a aprendizagem para as rotinas escolares, sem presumir que existe uma solução única.'] },
        { h2: 'Como construir uma parceria que faça diferença', p: ['O roteiro da Direção-Geral da Educação recomenda olhar para o ciclo de apoio e para a interação entre aluno e ambientes. Uma reunião breve, com dados concretos da escola e prioridades da criança, pode ajudar a escolher metas relevantes e reduzir mensagens contraditórias entre adultos.', 'A avaliação da educação inclusiva publicada em 2026 identifica progressos na colaboração, mas também desigualdades no acesso e gestão de recursos e desafios de articulação entre setores. Por isso, uma parceria deve ser descrita como um recurso previsto, não como garantia de que todas as escolas dispõem do mesmo número de horas ou profissionais.'], bullets: ['Definir uma meta funcional e um indicador simples para a rever.', 'Acordar os canais de comunicação e respeitar a confidencialidade.', 'Incluir a criança e a família nas decisões adequadas à sua idade.', 'Perguntar à escola como aceder ao apoio e a quem dirigir dúvidas.'] }
      ], summary: ['O CRI é um recurso especializado da comunidade que trabalha em parceria pedagógica com as escolas.', 'A modalidade e a disponibilidade variam; a escola mantém a responsabilidade pela resposta educativa e pela articulação.'], conclusion: 'Quando há objetivos comuns, responsabilidades claras e revisão regular, a especialização pode chegar mais facilmente aos contextos onde a criança aprende.' },
      en: { lead: 'A Portuguese Centre of Resources for Inclusion (CRI) is a specialist community service that may help a school respond to learning and participation needs. It is not an alternative school or a standard package for every child: it is a partnership shaped by assessment, goals and available resources.', sections: [
        { h2: 'What is a CRI and what can it offer?', p: ['Decree-Law 54/2018 describes CRIs as accredited specialist services that support schools’ capacity to promote educational success and inclusion. Teams may include speech and language therapists, occupational therapists, physiotherapists, psychologists or other professionals, depending on the provider and agreement in place.', 'Support may include direct intervention, observing activities, consultation, training and joint planning. The aim is to bring specialist skills closer to the settings where the child learns and participates, rather than working only on decontextualised goals. Formats and availability are not identical across regions.'] },
        { h2: 'The school remains responsible for education', p: ['A CRI complements the school; it does not replace teachers, the multidisciplinary team or the support measures organised by the school. Article 18 describes a pedagogical and developmental partnership. Specialist goals should connect to activities and pupil participation, with clear agreement on responsibilities and information-sharing.', 'Families can ask what goals are in the plan, when and where support happens, how professionals coordinate and what will be reviewed. If support takes place outside class, discuss why, for how long and how learning will transfer to school routines; there is no single model that fits every child.'] },
        { h2: 'Building a partnership that makes a difference', p: ['The Directorate-General for Education’s CRI guidance looks at the support cycle and the interaction between the pupil and their environments. A brief meeting using concrete school examples and the child’s priorities can help set useful goals and reduce conflicting messages between adults.', 'Portugal’s 2026 evaluation of inclusive education reports stronger collaboration as well as unequal access to and management of resources and challenges in cross-sector coordination. A CRI should therefore be described as a resource provided for in the system, not a guarantee that every school has the same professionals or hours.'], bullets: ['Agree on a functional goal and a simple way to review it.', 'Set communication channels and respect confidentiality.', 'Include the child and family in decisions in an age-appropriate way.', 'Ask the school how to access support and where to raise questions.'] }
      ], summary: ['A CRI is a specialist community resource that works in pedagogical partnership with schools.', 'Service models and availability vary; the school remains responsible for education and coordination.'], conclusion: 'With shared goals, clear responsibilities and regular review, specialist knowledge can reach the settings where children learn.' },
      es: { lead: 'Un Centro de Recursos para la Inclusión (CRI) portugués es un servicio especializado de la comunidad que puede ayudar a la escuela a responder a necesidades de aprendizaje y participación. No es una escuela alternativa ni un paquete igual para todos: es una colaboración que depende de la evaluación, los objetivos y los recursos disponibles.', sections: [
        { h2: '¿Qué es un CRI y qué puede ofrecer?', p: ['El Decreto-ley 54/2018 describe los CRI como servicios especializados acreditados que apoyan la capacidad de la escuela para promover el éxito educativo y la inclusión. Los equipos pueden incluir logopedas, terapeutas ocupacionales, fisioterapeutas, psicólogos u otros profesionales, según la entidad y el acuerdo vigente.', 'El apoyo puede incluir intervención directa, observación de actividades, asesoramiento, formación y planificación conjunta. La idea es acercar competencias especializadas a los contextos donde el niño aprende y participa, no trabajar solo objetivos descontextualizados. Los formatos y la disponibilidad varían entre territorios.'] },
        { h2: 'La escuela conserva la responsabilidad educativa', p: ['El CRI complementa a la escuela; no sustituye al docente, al equipo multidisciplinar ni a las medidas organizadas por el centro. El artículo 18 prevé una colaboración pedagógica y de desarrollo. Los objetivos especializados deben relacionarse con las actividades y la participación del alumno, acordando quién hace qué y cómo comparte información.', 'La familia puede preguntar qué objetivos recoge el plan, cuándo y dónde se presta el apoyo, cómo se coordinan los profesionales y qué se revisará. Si el apoyo se realiza fuera del aula, conviene hablar sobre el motivo, la duración y cómo se trasladará el aprendizaje a las rutinas escolares. No hay una única solución para todos.'] },
        { h2: 'Construir una colaboración útil', p: ['La guía de la Dirección General de Educación portuguesa sobre los CRI propone observar el ciclo de apoyo y la interacción entre alumno y entorno. Una reunión breve, con ejemplos escolares y prioridades del niño, ayuda a definir metas relevantes y reducir mensajes contradictorios.', 'La evaluación de la educación inclusiva publicada en 2026 señala avances en colaboración, pero también desigualdades en el acceso y gestión de recursos y dificultades de coordinación entre sectores. Por eso, el CRI es un recurso previsto en el sistema, no una garantía de que todos los centros tengan las mismas horas o profesionales.'], bullets: ['Definir un objetivo funcional y un indicador sencillo para revisarlo.', 'Acordar canales de comunicación y proteger la confidencialidad.', 'Incluir al niño y a la familia en las decisiones adecuadas a su edad.', 'Preguntar en la escuela cómo acceder al apoyo y a quién dirigir dudas.'] }
      ], summary: ['El CRI es un recurso especializado comunitario que colabora pedagógicamente con las escuelas.', 'La modalidad y disponibilidad varían; la escuela mantiene la responsabilidad educativa y de coordinación.'], conclusion: 'Con objetivos compartidos, responsabilidades claras y revisión periódica, la especialización puede llegar a los contextos donde aprende el niño.' }
    }, sources: ['Diário da República: <a href="https://diariodarepublica.pt/dr/legislacao-consolidada/decreto-lei/2018-115654476" target="_blank" rel="noopener">Decreto-Lei n.º 54/2018, artigo 18.º</a>.', 'DGE: <a href="https://dge.mec.pt/sites/default/files/EEspecial/necessidades_especiais_de_educacao_parceria_entre_a_escola_e_o_cri_uma_estrategia_para_a_inclusao.pdf" target="_blank" rel="noopener">Parceria entre a Escola e o CRI</a>.', 'CNE: <a href="https://www.cnedu.pt/pt/noticias/cne/avaliacao-da-educacao-inclusiva" target="_blank" rel="noopener">Avaliação da Educação Inclusiva (2026)</a>.'], related: ['inclusao-escolar-comunicacao', 'terapeuta-da-fala-na-escola']
  },
  {
    id: 'docente-educacao-especial-equipa', theme: 'escola', kind: { pt: 'Guia prático', en: 'Practical guide', es: 'Guía práctica' },
    pt: { slug: 'docente-educacao-especial-equipa', title: 'Professor de educação especial e docente titular: como trabalhar em equipa', teaser: 'O apoio especializado ganha impacto quando reforça a participação e o ensino na turma.' },
    en: { slug: 'special-education-teacher-teamwork', title: 'Special education and classroom teachers: how to work as a team', teaser: 'Specialist support has greater impact when it strengthens classroom teaching and participation.' },
    es: { slug: 'docente-educacion-especial-equipo', title: 'Docente de educación especial y tutor: cómo trabajar en equipo', teaser: 'El apoyo especializado mejora cuando refuerza la enseñanza y la participación en el aula.' },
    content: {
      pt: { lead: 'A inclusão não é um serviço separado que se entrega a um único profissional. O docente de educação especial tem conhecimento especializado, mas o currículo, as relações e as rotinas do grupo são partilhados com o docente titular ou diretor de turma e com a restante equipa.', sections: [
        { h2: 'Um papel de colaboração e diferenciação', p: ['O Decreto-Lei n.º 54/2018 descreve o docente de educação especial como dinamizador, articulador e especialista na diferenciação dos meios e materiais de aprendizagem e avaliação. Pode ajudar a antecipar barreiras, escolher recursos, adaptar instruções e planear formas variadas de participação, sem retirar ao professor da turma a responsabilidade pelo ensino.', 'O apoio pode decorrer em sala, em momentos de planeamento, em pequenos grupos ou noutros contextos definidos a partir das necessidades. A presença do docente de educação especial não deve significar que a criança deixa de pertencer à turma ou que apenas um adulto comunica com ela.'] },
        { h2: 'A coadjuvação precisa de tempo e objetivos claros', p: ['A colaboração funciona melhor quando ambos os docentes sabem o objetivo, combinam papéis e revêm evidências de aprendizagem. “Ajudar mais” não é um plano: importa saber se a criança consegue começar a tarefa, responder, interagir ou concluir uma atividade com menos barreiras.', 'A diferenciação pode manter a aprendizagem essencial e variar apoio, materiais, sequência, tempo ou forma de resposta. Quando as medidas curriculares mudam objetivos e conteúdos de forma significativa, a escola deve seguir o enquadramento formal aplicável, com participação da família e da equipa multidisciplinar.'] },
        { h2: 'Uma parceria que também escuta a criança', p: ['Família e aluno conhecem estratégias que funcionam noutros contextos e podem indicar o que é importante. Reuniões breves e registos simples ajudam a construir continuidade entre disciplinas e mudanças de ciclo. A criança deve ter oportunidades de expressar preferências e necessidades, com a forma de comunicação que utiliza.', 'O relatório nacional sobre práticas em dez escolas portuguesas descreve exemplos de planeamento, coadjuvação e colaboração com famílias. São casos documentados que podem inspirar reflexão; não demonstram que a mesma organização esteja disponível em todas as escolas nem garantem resultados iguais.'], bullets: ['Combinar previamente quem explica, modela, observa e dá feedback.', 'Partilhar materiais acessíveis com todos os docentes que acompanham a turma.', 'Medir progressos na participação e aprendizagem, não apenas no tempo de apoio.', 'Rever se a organização promove autonomia ou cria dependência de um adulto.'] }
      ], summary: ['O docente de educação especial colabora na diferenciação, articulação e acesso ao currículo.', 'O docente da turma mantém a responsabilidade pelo ensino; a criança continua a pertencer ao grupo.'], conclusion: 'Uma equipa inclusiva partilha conhecimento e responsabilidade para que o aluno participe mais, com apoios ajustados e objetivos comuns.' },
      en: { lead: 'Inclusion is not a separate service handed to one professional. A special education teacher brings specialist knowledge, while curriculum, relationships and classroom routines are shared with the class teacher and wider team.', sections: [
        { h2: 'A role based on collaboration and differentiation', p: ['Portugal’s Decree-Law 54/2018 describes the special education teacher as a facilitator, coordinator and specialist in differentiating learning and assessment materials and methods. They can help anticipate barriers, choose resources, adapt instructions and plan varied ways to participate, while the classroom teacher remains responsible for teaching.', 'Support may happen in class, during joint planning, in small groups or in other settings selected according to need. Having a special education teacher involved should not mean that the pupil stops belonging to the class or that only one adult communicates with them.'] },
        { h2: 'Co-teaching needs time and clear goals', p: ['Collaboration works best when both teachers understand the goal, agree on roles and review learning evidence. “More help” is not a plan: it matters whether the pupil can start a task, respond, interact or finish an activity with fewer barriers.', 'Differentiation can preserve essential learning while varying support, materials, sequence, time or response mode. When curriculum measures significantly change objectives or content, the school must follow the applicable formal process, with family and multidisciplinary-team participation.'] },
        { h2: 'A partnership that listens to the pupil', p: ['Families and pupils know strategies that work elsewhere and can identify what matters to them. Brief meetings and simple records help maintain continuity across subjects and school transitions. Pupils need opportunities to express preferences and needs through their preferred communication.', 'A national report on practice in ten Portuguese schools describes examples of planning, co-teaching and family collaboration. These documented cases can inform reflection; they do not show that the same arrangement is available in every school or guarantee the same outcomes.'], bullets: ['Agree who will explain, model, observe and give feedback.', 'Share accessible materials with all teachers working with the class.', 'Track learning and participation, not just support time.', 'Review whether the arrangement builds independence or dependence on one adult.'] }
      ], summary: ['Special education teachers collaborate on differentiation, coordination and curriculum access.', 'The classroom teacher remains responsible for teaching, and the pupil remains part of the class.'], conclusion: 'An inclusive team shares knowledge and responsibility so the pupil can participate more with appropriate support and common goals.' },
      es: { lead: 'La inclusión no es un servicio separado que se entrega a un único profesional. El docente de educación especial aporta conocimientos específicos, mientras que el currículo, las relaciones y las rutinas se comparten con el tutor y el resto del equipo.', sections: [
        { h2: 'Una función de colaboración y diferenciación', p: ['El Decreto-ley portugués 54/2018 describe al docente de educación especial como dinamizador, articulador y especialista en diferenciar medios y materiales de aprendizaje y evaluación. Puede ayudar a anticipar barreras, elegir recursos, adaptar instrucciones y planificar distintas formas de participar, sin quitar al tutor la responsabilidad de enseñar.', 'El apoyo puede darse en el aula, en la planificación conjunta, en grupos pequeños u otros contextos definidos según las necesidades. La participación del docente de educación especial no debe significar que el alumno deje de pertenecer al grupo o que solo un adulto se comunique con él.'] },
        { h2: 'La coenseñanza requiere tiempo y metas claras', p: ['La colaboración funciona mejor cuando ambos docentes conocen el objetivo, acuerdan funciones y revisan evidencias de aprendizaje. “Ayudar más” no es un plan: importa saber si el alumno puede iniciar la tarea, responder, interactuar o terminar una actividad con menos barreras.', 'La diferenciación puede mantener los aprendizajes esenciales y variar los apoyos, materiales, secuencia, tiempo o forma de responder. Cuando las medidas curriculares cambian significativamente objetivos o contenidos, la escuela debe seguir el procedimiento formal correspondiente con la familia y el equipo multidisciplinar.'] },
        { h2: 'Una colaboración que escucha al alumno', p: ['La familia y el alumno conocen estrategias útiles en otros contextos y pueden señalar qué es importante. Las reuniones breves y los registros sencillos ayudan a dar continuidad entre materias y cambios de ciclo. El alumno necesita oportunidades para expresar preferencias y necesidades usando su forma de comunicación.', 'Un informe nacional sobre prácticas en diez escuelas portuguesas describe ejemplos de planificación, coenseñanza y colaboración familiar. Son casos documentados que pueden inspirar reflexión, no prueban que la misma organización exista en todos los centros ni garantizan resultados iguales.'], bullets: ['Acordar quién explica, modela, observa y ofrece comentarios.', 'Compartir materiales accesibles con todos los docentes del grupo.', 'Registrar aprendizaje y participación, no solo horas de apoyo.', 'Revisar si la organización fomenta autonomía o dependencia de un adulto.'] }
      ], summary: ['El docente de educación especial colabora en la diferenciación, coordinación y acceso al currículo.', 'El tutor conserva la responsabilidad de enseñar y el alumno sigue perteneciendo al grupo.'], conclusion: 'Un equipo inclusivo comparte conocimientos y responsabilidad para que el alumno participe más con apoyos adecuados y metas comunes.' }
    }, sources: ['Diário da República: <a href="https://diariodarepublica.pt/dr/legislacao-consolidada/decreto-lei/2018-115654476" target="_blank" rel="noopener">Decreto-Lei n.º 54/2018, artigos 9.º, 10.º e 11.º</a>.', 'DGE: <a href="https://www.dge.mec.pt/node/2527" target="_blank" rel="noopener">Manual de apoio à prática inclusiva</a>.', 'Universidade de Évora / DGE: <a href="https://educacaoinclusiva.dge.mec.pt/sites/default/files/recursos/documentos/educacaoinclusivadavisaoaspraticaseducativaspromotorasdeequidadeeinclusaoem10escolasportuguesas.pdf" target="_blank" rel="noopener">Práticas em dez escolas portuguesas (2024)</a>.'], related: ['inclusao-escolar-comunicacao', 'centros-recursos-inclusao-escola']
  },
]

const langs = ['pt', 'en', 'es']
const brand = { pt: 'Fala+', en: 'Talk+', es: 'Habla+' }
const slugify = value => value.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '')
const escape = value => String(value).replace(/\\/g, '\\\\').replace(/`/g, '\\`').replace(/\$/g, '\\$')
function contentModule(article, lang) {
  const locale = article[lang]
  const text = article.content[lang]
  const sections = text.sections.map(section => [
    { h2: section.h2, id: slugify(section.h2), toc: section.h2 },
    ...section.p.map(p => ({ p })),
    ...(section.bullets ? [{ ul: section.bullets }] : []),
  ]).flat()
  return {
    id: article.id, slug: locale.slug, short: locale.title, date: '2026-10-18',
    titleTag: `${locale.title} · ${brand[lang]}`,
    description: locale.teaser,
    keywords: [locale.title.toLowerCase(), ...locale.teaser.toLowerCase().split(/[,.;:!? ]+/).filter(w => w.length > 5).slice(0, 5)],
    h1: `<span class="word-highlight">${locale.title}</span>`, lead: text.lead,
    blocks: [{ intro: text.lead }, ...sections, { summary: text.summary }, { h2: lang === 'pt' ? 'Em síntese' : lang === 'es' ? 'En síntesis' : 'In summary', id: 'conclusao', toc: lang === 'pt' ? 'Conclusão' : lang === 'es' ? 'Conclusión' : 'Conclusion' }, { p: text.conclusion }, { note: lang === 'pt' ? 'Conteúdo informativo. Não substitui avaliação individual nem orientação jurídica ou educativa.' : lang === 'es' ? 'Contenido informativo. No sustituye una evaluación individual ni orientación jurídica o educativa.' : 'Informational content. It does not replace individual assessment or legal or educational advice.' }],
    faq: text.faq || (lang === 'pt' ? [
      ['Este apoio é igual para todos os alunos?', 'Não. A resposta deve considerar os objetivos, as barreiras e as preferências de cada aluno e ser revista com base no que acontece no contexto escolar.'],
      ['Com quem posso esclarecer dúvidas?', 'Comece pelo docente titular ou diretor de turma e peça que indiquem quem coordena o apoio e quando será acompanhado. A EMAEI pode participar nos processos previstos na legislação.'],
    ] : lang === 'es' ? [
      ['¿Este apoyo es igual para todos los alumnos?', 'No. La respuesta debe tener en cuenta los objetivos, las barreras y las preferencias de cada alumno y revisarse según lo que ocurre en la escuela.'],
      ['¿Con quién puedo resolver dudas?', 'Puede empezar por el tutor y preguntar quién coordina el apoyo y cuándo se revisará. El equipo multidisciplinar puede participar en los procesos previstos por la legislación portuguesa.'],
    ] : [
      ['Is this support the same for every pupil?', 'No. Support should reflect each pupil’s goals, barriers and preferences, and be reviewed in light of what happens in school.'],
      ['Who can answer questions?', 'Start with the class teacher and ask who coordinates the support and when it will be reviewed. The multidisciplinary team may take part in the processes set out in Portuguese law.'],
    ]), sources: article.sources, related: article.related,
  }
}
for (const article of data) for (const lang of langs) {
  const dir = join(root, '_fonte', 'artigos', 'conteudo', lang)
  mkdirSync(dir, { recursive: true })
  const obj = contentModule(article, lang)
  writeFileSync(join(dir, `${article[lang].slug}.mjs`), `export default ${JSON.stringify(obj, null, 2)}\n`, 'utf8')
}
const catalog = data.map(article => ({
  id: article.id, theme: article.theme, kind: article.kind,
  ...Object.fromEntries(langs.map(lang => [lang, { live: true, slug: article[lang].slug, title: article[lang].title, teaser: article[lang].teaser }])),
}))
writeFileSync(join(root, '_fonte', 'artigos', 'catalogo-escola.mjs'), `export default ${JSON.stringify(catalog, null, 2)}\n`, 'utf8')
